def flatten(value,prefix=''):
    if isinstance(value,dict):
        for key,child in value.items():yield from flatten(child,prefix+'.'+key if prefix else key)
    elif isinstance(value,list):
        for index,child in enumerate(value):yield from flatten(child,f'{prefix}[{index}]')
    else:yield prefix,value

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--rust-cli',type=Path,default=ROOT/'dist/rusttran-linux-x86_64/rusttran-cli');parser.add_argument('--output',type=Path,default=ROOT/'analysis/component-comparison');args=parser.parse_args();binary=args.rust_cli.resolve();args.output.mkdir(parents=True,exist_ok=True)
