            source=ROOT/f'analysis/{fixture}_fixtures.json';doc=json.loads(source.read_text());reference_files.append(dict(path=str(source.relative_to(ROOT)),sha256=hashlib.sha256(source.read_bytes()).hexdigest(),method=doc['method']))
            before=len(rows);passed_cases=0
