                if fixture in ['feedwater_globals','process_storage','primary_references','fresh_auxiliary','startup_constants','startup_geometry','startup_clock','loop_transport']:actual=actual['stages'][0]['solution']
                if 'trace' in case:expected['trace']=case['trace']
                left,right=dict(flatten(expected)),dict(flatten(actual));passed=True
                if set(left)!=set(right):raise RuntimeError(f'{family} {index}: mismatched result fields')
                input_summary=', '.join(f'{k}={v:.7g}' for k,v in case['inputs'].items() if isinstance(v,(int,float)) and k in ['pressure','system_pressure','fraction','step','volume','clock','activation','phase_flag'])
                for field,e in left.items():
                    a=right[field]
                    if e is None:
                        if a is not None:raise RuntimeError(f'{family} {index} {field}: expected null')
                        continue
                    if isinstance(e,(bool,int)):
                        equal=type(a)==type(e) and a==e;ulp=0 if equal else abs(ordered(float(a))-ordered(float(e)));limit=0
                    elif tolerance is None or (fixture == 'fresh_initialized_state' and field.startswith(('alternate.doubles.', 'alternate.arrays.', 'alternate.temperatures[', 'model_doubles.'))):
                        ulp=None;equal=abs(a-e)<=max(1.,abs(e))*2e-13
                    else:
                        ulp=abs(ordered(a)-ordered(e));limit=min(tolerance,2) if 'trace.' in field else tolerance;equal=ulp<=limit
                    passed=passed and equal;difference=abs(float(a)-float(e))
                    rows.append(dict(test=len(rows)+1,function=family,inputs=f'case {index}: {field}; {input_summary}',original_x86=float(e),rusttran=float(a),absolute_difference=difference,relative_difference=difference/max(abs(float(e)),1e-300),float32_ulp=ulp,previous_derivative_matches=None,result='PASS' if equal else 'FAIL'))
                passed_cases+=passed;cases.append(dict(family=family,index=index,inputs=case['inputs'],expected=expected,actual=actual,result='PASS' if passed else 'FAIL'))
